import React, { useState } from 'react';
import './Header.css';

export function Header() {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  return (
    <header className="crust-crumb-header">
      <div className="container">
        <div className="brand-logo">
          <a href="#hero">
            <span className="logo-text">Crust & Crumb Bakery</span>
          </a>
        </div>
        <nav className="main-nav">
          <ul className="nav-list">
            <li><a href="#hero">Home</a></li>
            <li><a href="#menu">Menu</a></li>
            <li><a href="#about">About</a></li>
            <li><a href="#contact">Contact</a></li>
          </ul>
        </nav>
        <div className="action-buttons">
          <a href="mailto:reservations@dining.com" className="btn btn-primary">Reserve Now</a>
          <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="mobile-menu-toggle">
            <span className="bar"></span>
            <span className="bar"></span>
            <span className="bar"></span>
          </button>
        </div>
      </div>
      {isMobileMenuOpen && (
        <div className="mobile-menu">
          <a href="#hero" onClick={() => setIsMobileMenuOpen(false)}>Home</a>
          <a href="#menu" onClick={() => setIsMobileMenuOpen(false)}>Menu</a>
          <a href="#about" onClick={() => setIsMobileMenuOpen(false)}>About</a>
          <a href="#contact" onClick={() => setIsMobileMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}
