:root {
  --primary-color: #0b0f19;
  --primary-color-light: rgba(255, 255, 255, 0.08);
  --accent-color: #2563eb;
  --accent-color-dark: rgba(0, 0, 0, 0.3);
  --accent-color-light: rgba(255, 255, 255, 0.15);
  --font-heading: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;
  --bg-color: #0b0f19;
  --text-color: #0b0f19;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-family: var(--font-body, system-ui, sans-serif); }
body { margin: 0; font-family: var(--font-body, system-ui, sans-serif); background-color: var(--bg-color, #000000); color: var(--text-color, #ffffff); -webkit-font-smoothing: antialiased; }
.site-root { display: flex; flex-direction: column; min-height: 100vh; overflow-x: hidden; }

