          <article
            className={`bento-bento__card bento-bento__card--standard${activeItem === cardB.id ? ' is-active' : ''}`}
            onMouseEnter={() => setActiveItem(cardB.id)}
            onMouseLeave={() => setActiveItem(null)}
          >
