.bento-bento {
  position: relative;
  width: 100%;
  padding: 6rem 1.5rem;
  background: var(--surface-obsidian, var(--color-obsidian, var(--bg-color, #090d16)));
  color: var(--color-paper, var(--text-color, #ffffff));
}

.bento-bento__inner {
  max-width: var(--page-max-width, 1180px);
  margin: 0 auto;
}

.bento-bento__header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 3.5rem;
}

.bento-bento__eyebrow {
  display: inline-block;
  font-family: var(--font-heading, 'Plus Jakarta Sans', sans-serif);
  font-size: 0.8125rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-iridescent-fade, var(--accent-color, #38bdf8));
  margin-bottom: 0.75rem;
}

.bento-bento__title {
  font-family: var(--font-heading, 'Plus Jakarta Sans', sans-serif);
  font-size: clamp(2rem, 4vw, 2.75rem);
  font-weight: 800;
  color: var(--color-paper, var(--text-color, #ffffff));
  letter-spacing: -0.025em;
  line-height: 1.2;
  margin-bottom: 1rem;
}

.bento-bento__subtitle {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 1.05rem;
  color: var(--color-ash-mist, rgba(255, 255, 255, 0.7));
  line-height: 1.6;
}

.bento-bento__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: minmax(210px, auto);
  gap: 1.5rem;
}

.bento-bento__card {
  position: relative;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid #38bdf830;
  border-radius: var(--radius-cards, 12px);
  padding: var(--card-padding, 2rem);
  display: flex;
  flex-direction: column;
  transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
  overflow: hidden;
}

.bento-bento__card:hover {
  transform: translateY(-4px);
  border-color: var(--color-iridescent-fade, var(--accent-color, #38bdf8));
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.45);
}

/* Heterogeneous CSS Grid Spans */
.bento-bento__card--hero {
  grid-column: span 2;
  grid-row: span 2;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.05) 0%, rgba(255, 255, 255, 0.02) 100%);
}

.bento-bento__card--metric {
  grid-column: span 1;
  grid-row: span 2;
  justify-content: space-between;
}

.bento-bento__card--standard {
  grid-column: span 1;
  grid-row: span 1;
}

.bento-bento__card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.25rem;
}

.bento-bento__badge {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 0.25rem 0.65rem;
  background: var(--color-iridescent-fade, var(--accent-color, #38bdf8));
  color: var(--color-paper, #ffffff);
  border-radius: var(--radius-buttons, 12px);
}

.bento-bento__tag {
  font-size: 0.78rem;
  color: var(--color-ash-mist, rgba(255, 255, 255, 0.6));
  font-family: monospace;
}

.bento-bento__card-title {
  font-family: var(--font-heading, 'Plus Jakarta Sans', sans-serif);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-paper, #ffffff);
  margin-bottom: 0.75rem;
}

.bento-bento__card-title--hero {
  font-size: 1.65rem;
}

.bento-bento__card-desc {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.9375rem;
  color: var(--color-ash-mist, rgba(255, 255, 255, 0.7));
  line-height: 1.6;
  margin: 0 0 1.25rem;
}

.bento-bento__metric-wrap {
  margin: 1.5rem 0;
}

.bento-bento__metric-val {
  display: block;
  font-family: var(--font-heading, 'Plus Jakarta Sans', sans-serif);
  font-size: 3rem;
  font-weight: 800;
  color: var(--color-paper, #ffffff);
  line-height: 1;
  margin-bottom: 0.35rem;
}

.bento-bento__metric-label {
  font-size: 0.8125rem;
  color: var(--color-ash-mist, rgba(255, 255, 255, 0.55));
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.bento-bento__bar-meter {
  width: 100%;
  height: 6px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 999px;
  overflow: hidden;
  margin-top: 1rem;
}

.bento-bento__bar-fill {
  height: 100%;
  background: var(--color-iridescent-fade, var(--accent-color, #38bdf8));
  border-radius: 999px;
}

.bento-bento__hero-visual {
  margin-top: auto;
  padding-top: 1.5rem;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.bento-bento__pill-track {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.3rem 0.75rem;
  background: #38bdf815;
  border: 1px solid #38bdf830;
  border-radius: var(--radius-buttons, 16px);
  font-size: 0.75rem;
  color: var(--color-paper, #ffffff);
  margin-bottom: 0.75rem;
}

.bento-bento__status-dot {
  width: 6px;
  height: 6px;
  background: #10b981;
  border-radius: 50%;
}

.bento-bento__hero-code {
  background: rgba(0, 0, 0, 0.45);
  border: 1px solid #38bdf825;
  border-radius: var(--radius-cards, 12px);
  padding: 0.85rem 1rem;
  font-family: monospace;
  font-size: 0.8125rem;
  color: var(--color-ash-mist, #94a3b8);
  white-space: pre-wrap;
}

.bento-bento__card-action {
  margin-top: auto;
}

.bento-bento__link {
  color: var(--color-iridescent-fade, var(--accent-color, #38bdf8));
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  transition: opacity 0.15s ease;
}

.bento-bento__link:hover {
  opacity: 0.85;
}

@media (max-width: 900px) {
  .bento-bento__grid {
    grid-template-columns: 1fr;
  }
  .bento-bento__card--hero,
  .bento-bento__card--metric,
  .bento-bento__card--standard {
    grid-column: span 1;
    grid-row: auto;
  }
}

.bento-bento__card {
  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.25s ease, box-shadow 0.25s ease;
}
.bento-bento__card:hover {
  transform: translateY(-4px);
  border-color: #38bdf8;
  box-shadow: 0 12px 32px -8px rgba(0, 0, 0, 0.4);
}

/* Bento Image Entrance: span-weighted stagger matching parent card + smooth hover zoom */
.bento-bento__img-wrap {
  width: 100%;
  height: 160px;
  border-radius: var(--radius-cards, 12px);
  overflow: hidden;
  margin-bottom: 1rem;
}
.bento-bento__card-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0;
  transform: scale(1.03);
  transition: opacity 0.5s ease, transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);
  display: block;
}
.bento-bento__card--hero .bento-bento__card-img {
  animation: bentoBentoImageEnter 0.55s ease 0ms forwards;
}
.bento-bento__card--metric .bento-bento__card-img {
  animation: bentoBentoImageEnter 0.55s ease 100ms forwards;
}
.bento-bento__card--standard .bento-bento__card-img {
  animation: bentoBentoImageEnter 0.55s ease 200ms forwards;
}
@keyframes bentoBentoImageEnter {
  to { opacity: 1; transform: scale(1); }
}
.bento-bento__card:hover .bento-bento__card-img {
  transform: scale(1.04);
}

@media (prefers-reduced-motion: reduce) {
  .bento-bento__card,
  .bento-bento__card:hover,
  .bento-bento__link,
  .bento-bento__card-img,
  .bento-bento__card:hover .bento-bento__card-img {
    transform: none !important;
    transition: none !important;
    animation: none !important;
    box-shadow: none !important;
    opacity: 1 !important;
  }
}

/* ── Features Section Fade-In Motion Entrance ── */
@keyframes sectionFadeIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.bento-bento, .features, .features-section, [class*="features"] {
  animation: sectionFadeIn 0.75s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Accessibility: Mandatory prefers-reduced-motion fallback */
@media (prefers-reduced-motion: reduce) {
  .bento-bento, .features, .features-section, [class*="features"] {
    animation: none !important;
    transform: none !important;
    opacity: 1 !important;
  }
}

