  font-size: 1.05rem;
  color: var(--color-ash-mist, rgba(255, 255, 255, 0.7));
  line-height: 1.6;
}

.bento-bento__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: minmax(210px, auto);
  gap: 1.5rem;
