import React, { useState } from 'react';
import './Contact.css';

interface BentoItem {
  id: string;
  title: string;
  desc: string;
  tag: string;
  badge?: string;
  metric?: string;
  image?: string;
}

const BENTO_ITEMS: BentoItem[] = [{'id': 'item-1', 'title': 'Contact', 'desc': 'High-density modular capability for Contact.', 'tag': 'Core', 'badge': 'FLAGSHIP CAPABILITY', 'image': ''}, {'id': 'item-2', 'title': 'Predictive Telemetry & Tracing', 'desc': 'Deep flamegraphs and memory profiling across distributed execution clusters.', 'tag': 'Telemetry', 'metric': '99.98%', 'image': ''}, {'id': 'item-3', 'title': 'Cryptographic Ticket Auth', 'desc': 'Short-lived single-use HMAC-SHA256 authenticated tokens preventing cross-site session hijacking.', 'tag': 'Security', 'image': ''}, {'id': 'item-4', 'title': 'Heterogeneous Model Swarms', 'desc': 'Dynamically route drafting to high-efficiency local models and architectural critique to frontier LLMs.', 'tag': 'Swarm Architecture', 'image': ''}];

export function Contact() {
  const [activeItem, setActiveItem] = useState<string | null>(null);

  const heroItem = BENTO_ITEMS[0];
  const metricItem = BENTO_ITEMS[1];
  const cardA = BENTO_ITEMS[2];
  const cardB = BENTO_ITEMS[3];

  return (
    <section className="bento-bento" id="contact" aria-labelledby="bento-bento-title">
      <div className="bento-bento__inner">
        <div className="bento-bento__header">
          <span className="bento-bento__eyebrow">SYSTEM ARCHITECTURE</span>
          <h2 id="bento-bento-title" className="bento-bento__title">
            Contact
          </h2>
          <p className="bento-bento__subtitle">
            Heterogeneous card arrangements engineered for asymmetric visual hierarchy and instant scannability.
          </p>
        </div>

        <div className="bento-bento__grid">
          {/* 1. Hero Card — 2x2 Spanning Anchor */}
          <article
            className={`bento-bento__card bento-bento__card--hero${activeItem === heroItem.id ? ' is-active' : ''}`}
            onMouseEnter={() => setActiveItem(heroItem.id)}
            onMouseLeave={() => setActiveItem(null)}
          >
            <div className="bento-bento__card-top">
              <span className="bento-bento__badge">{heroItem.badge}</span>
              <span className="bento-bento__tag">{heroItem.tag}</span>
            </div>
            {heroItem.image && (
              <div className="bento-bento__img-wrap">
                <img src={heroItem.image} alt={heroItem.title} className="bento-bento__card-img" />
              </div>
            )}
            <div className="bento-bento__hero-body">
              <h3 className="bento-bento__card-title bento-bento__card-title--hero">
                {heroItem.title}
              </h3>
              <p className="bento-bento__card-desc">
                {heroItem.desc}
              </p>
            </div>
            <div className="bento-bento__hero-visual" aria-hidden="true">
              <div className="bento-bento__pill-track">
                <span className="bento-bento__status-dot" />
                <span>Active Runtime Verification Pipeline</span>
              </div>
              <div className="bento-bento__hero-code">
                <code>// Live Architecture Monitor
const status = await sandbox.validate({ isolation: 'strict' });</code>
              </div>
            </div>
          </article>

          {/* 2. Metric Card — 1x2 Tall Spanning Pillar */}
          <article
            className={`bento-bento__card bento-bento__card--metric${activeItem === metricItem.id ? ' is-active' : ''}`}
            onMouseEnter={() => setActiveItem(metricItem.id)}
            onMouseLeave={() => setActiveItem(null)}
          >
            <div className="bento-bento__card-top">
              <span className="bento-bento__tag">{metricItem.tag}</span>
            </div>
            {metricItem.image && (
              <div className="bento-bento__img-wrap">
                <img src={metricItem.image} alt={metricItem.title} className="bento-bento__card-img" />
              </div>
            )}
            <div className="bento-bento__metric-wrap">
              <span className="bento-bento__metric-val">{metricItem.metric}</span>
              <span className="bento-bento__metric-label">Benchmark Accuracy</span>
            </div>
            <h3 className="bento-bento__card-title">{metricItem.title}</h3>
            <p className="bento-bento__card-desc">{metricItem.desc}</p>
            <div className="bento-bento__bar-meter" role="progressbar" aria-valuenow={98} aria-valuemin={0} aria-valuemax={100}>
              <div className="bento-bento__bar-fill" style={{ width: '98%' }} />
            </div>
          </article>

          {/* 3. Modular Feature Card A — 1x1 Span */}
          <article
            className={`bento-bento__card bento-bento__card--standard${activeItem === cardA.id ? ' is-active' : ''}`}
            onMouseEnter={() => setActiveItem(cardA.id)}
            onMouseLeave={() => setActiveItem(null)}
          >
            <div className="bento-bento__card-top">
              <span className="bento-bento__tag">{cardA.tag}</span>
            </div>
            {cardA.image && (
              <div className="bento-bento__img-wrap">
                <img src={cardA.image} alt={cardA.title} className="bento-bento__card-img" />
              </div>
            )}
            <h3 className="bento-bento__card-title">{cardA.title}</h3>
            <p className="bento-bento__card-desc">{cardA.desc}</p>
            <div className="bento-bento__card-action">
              <a href="#contact" className="bento-bento__link">
                View Specification &rarr;
              </a>
            </div>
          </article>

          {/* 4. Modular Feature Card B — 1x1 Span */}
          <article
            className={`bento-bento__card bento-bento__card--standard${activeItem === cardB.id ? ' is-active' : ''}`}
            onMouseEnter={() => setActiveItem(cardB.id)}
            onMouseLeave={() => setActiveItem(null)}
          >
            <div className="bento-bento__card-top">
              <span className="bento-bento__tag">{cardB.tag}</span>
            </div>
            {cardB.image && (
              <div className="bento-bento__img-wrap">
                <img src={cardB.image} alt={cardB.title} className="bento-bento__card-img" />
              </div>
            )}
            <h3 className="bento-bento__card-title">{cardB.title}</h3>
            <p className="bento-bento__card-desc">{cardB.desc}</p>
            <div className="bento-bento__card-action">
              <a href="#contact" className="bento-bento__link">
                Explore Documentation &rarr;
              </a>
            </div>
          </article>
        </div>
      </div>
    </section>
  );
}

