.Header {
  position: sticky;
  top: 0;
  z-index: 100;
  width: 100%;
  background: var(--color-bg);
  border-bottom: 1px solid var(--color-border);
  box-shadow: 0 0 16px rgba(0, 0, 0, 0.08);
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  transform: translateY(0);
  opacity: 1;
}

.Header__inner {
  max-width: var(--page-max-width);
  margin: 0 auto;
  padding: 12px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.Header__brand {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-heading);
  text-decoration: none;
  letter-spacing: 0.04em;
}

.Header__nav {
  display: flex;
  align-items: center;
}

.Header__list {
  list-style: none;
  display: flex;
  gap: 24px;
  margin: 0;
}

.Header__item {
  &:last-child {
    margin-right: 0;
  }
}

.Header__link {
  color: var(--color-text);
  text-decoration: none;
  font-size: 0.92rem;
  font-weight: 500;
  transition: color 0.2s ease;
}

.Header__link:hover {
  color: var(--accent-color);
}

.Header__actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.Header__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 16px;
  background: var(--accent-color);
  color: var(--color-bg);
  font-size: 0.92rem;
  font-weight: 600;
  text-decoration: none;
  border-radius: var(--radius-buttons);
  transition: all 0.2s ease;
}

.Header__btn:hover {
  background: var(--accent-color-dark);
}

.Header__toggle {
  display: none;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 8px;
}

.Header__bar {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--color-text);
  margin: 4px 0;
}

.Header__drawer {
  position: fixed;
  top: 64px;
  left: 0;
  width: 100%;
  background: var(--color-surface);
  padding: 24px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
  border-top: 1px solid var(--color-border);
  z-index: 101;
}

.Header__close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  background: var(--color-bg);
  border: 2px solid var(--color-text);
  border-radius: 50%;
  cursor: pointer;
  transition: all 0.2s ease;
}

.Header__close:hover {
  background: var(--accent-color);
  border-color: var(--accent-color);
}

@media (prefers-reduced-motion: reduce) {
  .Header,
  .Header__drawer {
    transition: none;
    transform: none;
    opacity: 1 !important;
  }
}

@media (max-width: 768px) {
  .Header__nav {
    display: none;
  }

  .Header__toggle {
    display: flex;
  }
}

