import React, { useState, useEffect } from 'react';
import './Header.css';

interface NavLink {
  label: string;
  href: string;
}

const NAV_LINKS: NavLink[] = [
  { label: 'Home', href: '#' },
  { label: 'Features', href: '#features' },
  { label: 'Pricing', href: '#pricing' },
  { label: 'Blog', href: '#' },
  { label: 'Contact', href: '#' }
];

const Header: React.FC = () => {
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 64);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`header ${scrolled ? 'header--scrolled' : ''}`}>
      <div className="header__inner">
        <a href="#" className="header__brand">
          <span className="header__logo">NexaFlow</span>
          <small className="header__tagline">Operational intelligence and automated release cycles for distributed engineering teams</small>
        </a>
        <nav className="header__nav">
          <ul className="header__nav-list">
            {NAV_LINKS.map((link, index) => (
              <li key={index} className="header__nav-item">
                <a href={link.href} className="header__nav-link">{link.label}</a>
              </li>
            ))}
          </ul>
        </nav>
        <div className="header__actions">
          <a href="#cta" className="btn btn--primary btn--pill">Get Started</a>
          <button
            type="button"
            className="header__mobile-toggle"
            aria-label="Toggle navigation menu"
            onClick={() => setIsDrawerOpen(!isDrawerOpen)}
          >
            <span className="sr-only">Toggle navigation menu</span>
            <span className="icon icon--hamburger" />
          </button>
        </div>
      </div>
      {isDrawerOpen && (
        <div className="header__drawer">
          <button
            type="button"
            className="header__drawer-close"
            aria-label="Close navigation drawer"
            onClick={() => setIsDrawerOpen(false)}
          >
            <span className="sr-only">Close navigation drawer</span>
            <span className="icon icon--close" />
          </button>
          <nav className="header__drawer-nav">
            <ul className="header__drawer-list">
              {NAV_LINKS.map((link, index) => (
                <li key={index} className="header__drawer-item">
                  <a href={link.href} className="header__drawer-link">{link.label}</a>
                </li>
              ))}
            </ul>
          </nav>
          <div className="header__drawer-footer">
            <a href="#cta" className="btn btn--primary btn--pill">Get Started</a>
          </div>
        </div>
      )}
    </header>
  );
};

export default Header;

